// 视频导出警告的展示逻辑（纯函数）。

import { describe, expect, it } from 'vitest';

import type { VideoExportWarning } from '../src/commands/videoExport';
import { summarizeWarnings, warningLocation } from '../src/lib/videoExportWarnings';

function warning(patch: Partial<VideoExportWarning> = {}): VideoExportWarning {
  return {
    code: 'WG_ANIMATION_FORMAT',
    message: 'v2 keyframes 动画暂不支持',
    scene: 'start.txt',
    line: 12,
    ...patch,
  };
}

describe('warningLocation', () => {
  it('把场景与行号拼成 场景:行号', () => {
    expect(warningLocation(warning())).toBe('start.txt:12');
  });

  it('只有场景时只给场景', () => {
    expect(warningLocation(warning({ line: null }))).toBe('start.txt');
  });

  it('只有行号时给 第 N 行', () => {
    expect(warningLocation(warning({ scene: null }))).toBe('第 12 行');
  });

  it('两者都缺时为空串', () => {
    expect(warningLocation(warning({ scene: null, line: null }))).toBe('');
    expect(warningLocation(warning({ scene: '  ', line: 0 }))).toBe('');
  });
});

describe('summarizeWarnings', () => {
  it('空列表', () => {
    expect(summarizeWarnings([])).toEqual({ total: 0, shown: [], hidden: 0 });
  });

  it('去重后计数, 且 shown + hidden 等于 total', () => {
    const summary = summarizeWarnings([warning(), warning(), warning({ line: 13 })], 5);
    expect(summary.total).toBe(2);
    expect(summary.shown).toHaveLength(2);
    expect(summary.hidden).toBe(0);
  });

  it('超过上限时只给前几条并报告剩余', () => {
    const list = Array.from({ length: 8 }, (_, index) => warning({ line: index + 1 }));
    const summary = summarizeWarnings(list, 3);
    expect(summary.total).toBe(8);
    expect(summary.shown).toHaveLength(3);
    expect(summary.hidden).toBe(5);
  });

  it('limit 至少为 1', () => {
    const summary = summarizeWarnings([warning(), warning({ line: 13 })], 0);
    expect(summary.shown).toHaveLength(1);
    expect(summary.hidden).toBe(1);
  });
});
